//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
scwin.pMenuID = $c.stf.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.clickBzProcsNo;
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 회사선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.vPageTYp = '2';
scwin.vSYMBL_INPUT_CD;
scwin.TR_JOB;
scwin.TR_ROW_POS;
scwin.gIsurCd;
scwin.gComAbbrv;
scwin.gSecugrpId;
scwin.gMktTpCd;
scwin.gAcptNo;
scwin.gAcptSeq;
scwin.gAcptNoListFee;
scwin.vScrenID = "ULDSTF05201.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_searchCode = function() {
    /*
    00722 - 상호변경사유
    */
    var arrCid = [{
        cid: "COM_CHG_RSN_CD",
        cnm: "cmb_COM_CHG_RSN_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='COM_CHG_RSN_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_COM_NM.getValue(); // 발행기관명
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        scwin.fr_SecuGrpId = arrPar[0].SECUGRP_ID;
        $c.lic.fn_gridNameChange(scwin.fr_SecuGrpId);
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD;
        scwin.vSYMBL_INPUT_CD = scwin.vSPOT_ISU_TRD_MKT_TP_CD;
        //alert('[vSPOT_ISU_TRD_MKT_TP_CD]'+vSPOT_ISU_TRD_MKT_TP_CD);
        scwin.fn_setSymblObj();
        btn_Search.trigger("onclick");
    }
};
scwin.fn_setSymblObj = function() {
    if (scwin.vSYMBL_INPUT_CD == '1') {
        $c.stf.showObj(panel_ISUR_SYMBL, true);
        $c.cm.setColumnProp(grd_IsuNm, "BFCHG_ISU_ENG_SYMBL", "Show", true);
        $c.cm.setColumnProp(grd_IsuNm, "AFCHG_ISU_ENG_SYMBL", "Show", true);
        $c.cm.setColumnProp(grd_HisCoNm, "AFCHG_ISUR_SYMBL", "Show", true);
        $c.cm.setColumnProp(grd_HisIsuNm, "AFCHG_ISU_ENG_SYMBL", "Show", true);
    } else if (scwin.vSYMBL_INPUT_CD == '2' || scwin.vSYMBL_INPUT_CD == "6") {
        $c.stf.showObj(panel_ISUR_SYMBL, false);
        $c.cm.setColumnProp(grd_IsuNm, "BFCHG_ISU_ENG_SYMBL", "Show", false);
        $c.cm.setColumnProp(grd_IsuNm, "AFCHG_ISU_ENG_SYMBL", "Show", false);
        $c.cm.setColumnProp(grd_HisCoNm, "AFCHG_ISUR_SYMBL", "Show", false);
        $c.cm.setColumnProp(grd_HisIsuNm, "AFCHG_ISU_ENG_SYMBL", "Show", false);
    }
};



/**
 * 원장데이타  조회
 */
scwin.fn_conm_chg_read_sync = function() {
    var url = "/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchComNmChgList" + "&DIV_IDX=" + DIV_IDX_COM_NM_CURR_LIST + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    dts_CoNm.DataID = encodeURI(url);
    dts_CoNm.Reset();
    url = "/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchComNmChgList" + "&DIV_IDX=" + DIV_IDX_ISU_NM_CURR_LIST + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    dts_IsuNm.DataID = encodeURI(url);
    dts_IsuNm.Reset();

    /* 2009.07.13 상호변경 히스토리 목록 */
    url = "/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchComNmChgList" + "&DIV_IDX=" + DIV_IDX_COM_NM_CURR_HIST_LIST + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    dts_CoNm_History.DataID = encodeURI(url);
    dts_CoNm_History.Reset();

    /* 2009.07.13 종목명 히스토리 목록 */
    url = "/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchComNmChgList" + "&DIV_IDX=" + DIV_IDX_ISU_NM_CURR_HIST_LIST + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    dts_IsuNm_History.DataID = encodeURI(url);
    dts_IsuNm_History.Reset();
};




/**
 * 주식발행내역 목록 조회
 */
scwin.fn_iss_list_sync = function() {
    var url = "/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchIsuIssChgList" + "&DIV_IDX=" + DIV_IDX_ISS_STK_HIST + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    dts_IssList.DataID = encodeURI(url);
    dts_IssList.Reset();
    $c.cm.ShowWin(grd_IssList);
    url = "/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchIsuIssChgList" + "&DIV_IDX=" + DIV_IDX_ISS_STK_RECV + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&GUBUN_CD=2&GUBUN_CD=2";
    dts_IssRecv.DataID = encodeURI(url);
    dts_IssRecv.Reset();
};


/**
 * 접수문서가 상호변경인지 체크
 */
scwin.fn_read_recv_comnmyn_sync = function(pAcptNo) {
    var url = "/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchIsuIssChgList" + "&DIV_IDX=" + DIV_IDX_ISS_STK_RECV_COM_NM_CHG_YN + "&ACPT_NO=" + pAcptNo;
    dts_RecvCoNmYn.DataID = encodeURI(url);
    dts_RecvCoNmYn.Reset();
};
scwin.fn_setBzProcsNo = function(obj) {
    scwin.clickBzProcsNo = dts_IssList.getCellData(eval(obj), "BZ_PROCS_NO");

    //상장수수료로 인해 추가 TBLD_LIST_APPL_FORM 테이블에 접수번호가 없으면 SMS전송 버튼이 보이지 않음
    scwin.gAcptNoListFee = dts_IssList.getCellData(eval(obj), "ACPT_NO");
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=LIST_FEE_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.select.list.acptno" + "&{P}param01=" + scwin.gAcptNoListFee; // 사용자 ID

    dts_IssListAcptNo.DataID = encodeURI(url);
    dts_IssListAcptNo.Reset();
    scwin.gAcptNoListFee = dts_IssListAcptNo.getCellData(1, "ACPT_NO");

    //alert("fn_setBzProcsNo():"+clickBzProcsNo);

};
scwin.fn_getBzProcsNo = function() {
    return scwin.clickBzProcsNo;
};
scwin.fn_OpenDetailExtr = function(row) {
    var secugrpId = scwin.fr_SecuGrpId;
    scwin.clickBzProcsNo = ""; //초기화
    scwin.gAcptNo = dts_IssRecv.getCellData(row, "ACPT_NO");
    scwin.gAcptNoListFee = scwin.gAcptNo;
    //gAcptNo = "20080616007146";
    scwin.gAcptSeq = dts_IssRecv.getCellData(row, "BYACPTNO_SEQ");
    $c.lic.fn_OpenDetailIssMng(txb_ISUR_CD, scwin.fr_SecuGrpId, scwin.gAcptNo);
};


/**
 * 상장종목팝업창
 */
scwin.fn_OpenDetailCorpIsu = function(row) {
    scwin.gAcptNo = ""; //초기화
    scwin.gAcptSeq = ""; //초기화
    scwin.gAcptNoListFee = ""; //초기화
    if (row > 0) {
        //그리드에서 선택시
        scwin.fn_setBzProcsNo(row);
    } else {
        //신규버튼 선택시
        scwin.clickBzProcsNo = ""; //초기화

    }
    //alert("[fn_OpenDetail secugrpId]"+secugrpId);
    $c.lic.fn_OpenDetailIssMng(txb_ISUR_CD, scwin.fr_SecuGrpId, scwin.clickBzProcsNo);
};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사]를 선택하세요.");
        txb_ISUR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_MKTACT_ENFORCE_DD) == "") {
        $c.win.alert("[변경상장일]을 입력하세요.");
        edt_MKTACT_ENFORCE_DD.focus();
        return false;
    }
    if (vCurDate >= $c.stf.getObjectValue(edt_MKTACT_ENFORCE_DD)) {
        $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
        edt_MKTACT_ENFORCE_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_COM_CHG_RSN_CD) == "") {
        $c.win.alert("[변경사유]를 선택하세요.");
        cmb_COM_CHG_RSN_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_AFCHG_COM_NM) == "") {
        $c.win.alert("[한글회사명]을 입력하세요.");
        txb_AFCHG_COM_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_AFCHG_COM_NM, 60, "한글회사명")) return false;
    if ($c.stf.getObjectValue(txb_AFCHG_COM_ABBRV) == "") {
        $c.win.alert("[한글회사약명]을 입력하세요.");
        txb_AFCHG_COM_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_AFCHG_COM_ABBRV, 30, "한글회사약명")) return false;
    if ($c.stf.getObjectValue(txb_AFCHG_COM_ENG_NM) == "") {
        $c.win.alert("[영문회사명]을 입력하세요.");
        txb_AFCHG_COM_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_AFCHG_COM_ENG_NM, 60, "영문회사명")) return false;
    if ($c.stf.getObjectValue(txb_AFCHG_COM_ENG_ABBRV) == "") {
        $c.win.alert("[영문회사약명]을 입력하세요.");
        txb_AFCHG_COM_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_AFCHG_COM_ENG_ABBRV, 30, "영문회사약명")) return false;
    if (scwin.vSYMBL_INPUT_CD == '1') {
        if ($c.stf.getObjectValue(txb_AFCHG_ISUR_SYMBL) == "") {
            $c.win.alert("[영문회사심볼]을 입력하세요.");
            txb_AFCHG_ISUR_SYMBL.focus();
            return false;
        }
        if (!$c.lc.fn_chkCorpSymblDoubleInput($c.stf.getObjectValue(txb_AFCHG_ISUR_SYMBL), $c.stf.getObjectValue(txb_ISUR_CD), dts_Symbl)) {
            $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
            return false;
        }
    }

    /* 2009-04-24 상호변경 중복입력체크 */
    ///*
    if (!$c.lc.fn_check_bz_doubleinput(dts_BZ_CHECK, $c.stf.getObjectValue(txb_ISUR_CD), $c.stf.getObjectValue(edt_MKTACT_ENFORCE_DD), scwin.vBzProcsNo, LIST_BZ_TP_CD_148)) {
        return false;
    }
    return true;
};
scwin.fn_trs = function(trsIdx) {
    var vScrenProcTpCd;
    if (scwin.TR_JOB == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    grd_IsuNm.redraw = false;
    for (var i = 1; i <= dts_IsuNm.getTotalRow(); i++) {
        dts_IsuNm.setCellData(i, "BZ_PROCS_NO", scwin.vBzProcsNo);
        //dts_IsuNm.NameString(i, "BZ_PROCS_NO") = fn_getNewBzProcNo( dts_BzProcsNo ); //DB변경후 바꾸자...
        dts_IsuNm.setCellData(i, "MKTACT_ENFORCE_DD", dts_CoNm.getCellData(1, "MKTACT_ENFORCE_DD"));
    }
    grd_IsuNm.redraw = true;
    trs_Save.Action = $c.lc.fn_encodeNSession("/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveChgList");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I: dtsParm1= dts_CoNm , I:dtsParm2= dts_IsuNm)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",COUNT=2" + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_148 + ",DIV_IDX[0]=" + DIV_IDX_STK_COMNM_CHG + ",DIV_IDX[1]=" + DIV_IDX_STK_ISUNM_CHG;
    trs_Save.Post();
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (dts_IsuNm.getCellData(1, "AFCHG_ISU_KOR_NM") == "") {
            $c.win.alert("[종목명자동생성] 버튼을 선택하면 '변경후 종목명정보'가 자동 설정됩니다.");
            return;
        }
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dts_CoNm.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            dts_CoNm.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
            scwin.fn_trs(TRS_IDX_INSERT);
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TRS_IDX_UPDATE);
    }
};
scwin.fn_delete = function() {
    scwin.TR_JOB = 'D';
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.fn_trs(TRS_IDX_DELETE);
};


/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_Iss_ExcelDown = function() {
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_IssList, "주식발행내역", "", "8");
};
scwin.fn_getIsuNmDisclsCtnt = function() {
    var vCtnt = "";
    vCtnt += "\r\n";
    vCtnt += "1. 변경내역(변경전 → 변경후)";
    vCtnt += "\r\n";
    vCtnt += "    - 한글종목명";
    vCtnt += "\r\n";
    for (var i = 1; i <= dts_IsuNm.getTotalRow(); i++) {
        vCtnt += "         o " + dts_IsuNm.getCellData(i, "BFCHG_ISU_KOR_NM") + " → " + dts_IsuNm.getCellData(i, "AFCHG_ISU_KOR_NM");
        vCtnt += "\r\n";
    }
    vCtnt += "    - 영문종목명";
    vCtnt += "\r\n";
    for (var i = 1; i <= dts_IsuNm.getTotalRow(); i++) {
        vCtnt += "         o " + dts_IsuNm.getCellData(i, "BFCHG_ISU_ENG_NM") + " → " + dts_IsuNm.getCellData(i, "AFCHG_ISU_ENG_NM");
        vCtnt += "\r\n";
    }
    vCtnt += "2. 변경일자: " + scwin.dateForm($c.stf.getObjectValue(edt_MKTACT_ENFORCE_DD));
    vCtnt += "\r\n";
    vCtnt += "3. 변경사유: ★★★★★★★★★★★★";
    vCtnt += "\r\n";
    return vCtnt;
};
scwin.dateForm = function(pStr) {
    var str = "";
    if (pStr == "") {
        str = "★★★★년" + "★★월" + "★★일";
    } else {
        str = pStr.substring(0, 4) + "년" + pStr.substring(4, 6) + "월" + pStr.substring(6, 8) + "일";
    }
    return str;
};
scwin.fn_dscl = async function() {
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    if ((txb_ISUR_CD.getValue() == "") || (edt_MKTACT_ENFORCE_DD.getValue() == "")) {
        $c.win.alert("발행기관 코드 혹은 변경상장일 자료가 없습니다.");
        return;
    }
    if (scwin.vBzProcsNo == "") {
        $c.win.alert("먼저 저장하신후 선택하시기 바랍니다.");
        return;
    }
    if ($c.cp.isModified(dts_CoNm) || $c.cp.isModified(dts_IsuNm)) {
        $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }
    var chgTyp = dts_CoNm.getCellData(dts_CoNm.getRowPosition(), "COM_CHG_RSN_CD");
    if ((chgTyp == "11") || (chgTyp == "12")) {
