scwin.fn_stkkndcd_read_sync = function(vCode) {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=STK_KND_CD_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstlst.select.stkkndcd.condition" + "&{P}param01=" + vCode;
    dts_STK_KND_CD.DataID = encodeURI(url);
    dts_STK_KND_CD.reset();
};
scwin.fn_changeIsuNmByBatch = function() {
    if (!scwin.fn_CheckForm()) return false;
    grd_IsuNmredraw = false;
    var gAfComNm = dts_CoNm.getCellData(1, "AFCHG_COM_NM");
    var repCoNm = gAfComNm.replace("(주)", "");
    repCoNm = repCoNm.replace("㈜", "");
    repCoNm = repCoNm.replace("주식회사", "");
    var gAfComEngNm = dts_CoNm.getCellData(1, "AFCHG_COM_ENG_NM");
    var repCoEngNm = gAfComEngNm.replace("CO., LTD.", "");
    repCoEngNm = repCoEngNm.replace("CO.,LTD.", "");
    repCoEngNm = repCoEngNm.replace("CO.,LTD.", "");
    repCoEngNm = repCoEngNm.replace("CO., LTD", "");
    repCoEngNm = repCoEngNm.replace("CO.,LTD", "");
    repCoEngNm = repCoEngNm.replace("Co., Ltd", "");
    for (var i = 1; i <= dts_IsuNm.getTotalRow(); i++) {
        var gStkcertKndCd = dts_IsuNm.getCellData(i, "STKCERT_KIND_CD");
        scwin.fn_stkkndcd_read_sync(gStkcertKndCd);
        var vPreStr = "";
        var vPreEngStr = "";
        var gCompressCD = "";
        if (gStkcertKndCd != '000') {
            gCompressCD = dts_STK_KND_CD.getCellData(1, "COMPRESS_CD");
        }
        var vStkKndSNm = dts_STK_KND_CD.getCellData(1, "STK_KND_SNM");
        var vStkKndEngNm = dts_STK_KND_CD.getCellData(1, "STK_KND_ENG_NM");
        var vStkKndEngSNm = dts_STK_KND_CD.getCellData(1, "STK_KND_ENG_SNM");
        var gPrefStkTpCd = dts_IsuNm.getCellData(i, "PREFSTK_TP_CD");
        if (gPrefStkTpCd == '2') {
            vPreStr = "(신형)";
            vStkKndSNm = vStkKndSNm + "B";
            vStkKndEngNm = vStkKndEngNm.replace("P", "PB");
            vStkKndEngSNm = vStkKndEngSNm.replace("P", "PB");
        }
        dts_IsuNm.setCellData(i, "AFCHG_ISU_KOR_NM", repCoNm + dts_STK_KND_CD.getCellData(1, "STK_KND_NM") + vPreStr);
        dts_IsuNm.setCellData(i, "AFCHG_ISU_KOR_ABBRV", dts_CoNm.getCellData(1, "AFCHG_COM_ABBRV") + vStkKndSNm);
        dts_IsuNm.setCellData(i, "AFCHG_ISU_ENG_NM", repCoEngNm + vStkKndEngNm);
        dts_IsuNm.setCellData(i, "AFCHG_ISU_ENG_ABBRV", dts_CoNm.getCellData(1, "AFCHG_COM_ENG_ABBRV") + vStkKndEngSNm);
        dts_IsuNm.setCellData(i, "AFCHG_ISU_ENG_SYMBL", dts_CoNm.getCellData(1, "AFCHG_ISUR_SYMBL") + gCompressCD);
    }
    grd_IsuNm.redraw = true;
    return true;
};
scwin.btn_isunm_batch_change_onclick = function() {
    scwin.fn_changeIsuNmByBatch();
};
