scwin.gform_onload = function() {
    $c.elw.fn_searchCode();
    $c.cm.PanelToGroupBox(panel_Top);
    $c.libRoundPanel.PanelToGroupBox(panel_CoNmChg_Item);
    scwin.vSYMBL_INPUT_CD = js_market;
    scwin.fn_setSymblObj();
    MxTab_1.setSelectedTabIndex(2);

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성

    var parentWin = $c.lc.fn_GetRecvDocProvider();
    if (scwin.gIsurCd != "" && scwin.gIsurCd != undefined) {
        txb_ISUR_CD.setValue(scwin.gIsurCd);
        txb_COM_NM.setValue(scwin.gComAbbrv);
        scwin.fr_SecuGrpId = scwin.gSecugrpId;
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = scwin.gMktTpCd;
        $c.lic.fn_gridNameChange(scwin.fr_SecuGrpId);
        scwin.fn_read_recv_comnmyn_sync(scwin.gAcptNo);
        if (dts_RecvCoNmYn.getCellData(1, "CHECK_YN") == 'Y') {
            MxTab_1.setSelectedTabIndex(1); //상호변경탭으로 이동

        }
        btn_Search.trigger("onclick");
    } else {
        buttonSet.setInsertStatus();
    }
};
